#include "tigersheets/main_window.hpp"
#include "tigersheets/chart.hpp"
#include "tigersheets/ooxml.hpp"
#include <QApplication>
#include <QDialog>
#include <QDialogButtonBox>
#include <QLineEdit>
#include <QPushButton>
#include <QPointer>
#include <QTableView>
#include <QTemporaryDir>
#include <QTimer>
#include <QTest>
#include <iostream>
#include <stdexcept>
using namespace tigersheets;
void require(bool ok,const char* message){if(!ok)throw std::runtime_error(message);}
ChartWidget* firstChart(MainWindow& window){for(auto* widget:window.findChildren<QWidget*>())if(auto* chart=dynamic_cast<ChartWidget*>(widget))return chart;return nullptr;}
void editFigure(){MainWindow window;window.loadFinancialExample();window.show();QApplication::processEvents();auto* chart=firstChart(window);require(chart,"native chart exists");const auto before=window.currentSession().snapshot();bool edited=false;
 QTimer::singleShot(0,&window,[&]{if(auto* dialog=window.findChild<QDialog*>("chartEditor")){auto* title=dialog->findChild<QLineEdit*>("chartTitle");auto* buttons=dialog->findChild<QDialogButtonBox*>("chartDialogButtons");if(title&&buttons){title->setText("Updated financial forecast");edited=true;buttons->button(QDialogButtonBox::Ok)->click();}}});
 QTest::mouseDClick(chart,Qt::LeftButton,Qt::NoModifier,QPoint(140,26));QApplication::processEvents();
 require(edited,"double-clicking a figure must open its chart editor");const auto after=window.currentSession().snapshot();require(after["charts"][0]["title"]=="Updated financial forecast"&&after["charts"][0]["id"]==before["charts"][0]["id"]&&after["sheets"]==before["sheets"],"editing must update the existing chart without altering worksheet data");
 require(window.executeCommand("undo")&&window.currentSession().snapshot()["charts"]==before["charts"],"chart edit must be one undo transaction");}
void deleteFigure(){MainWindow window;window.loadFinancialExample();window.show();QApplication::processEvents();auto* chart=firstChart(window);require(chart,"native chart exists");const auto before=window.currentSession().snapshot();QTest::mouseClick(chart,Qt::LeftButton,Qt::NoModifier,QPoint(120,25));QTest::keyClick(chart,Qt::Key_Delete);QApplication::processEvents();const auto after=window.currentSession().snapshot();require(after["charts"].empty()&&after["sheets"]==before["sheets"],"Delete must remove the selected chart without clearing worksheet cells");require(window.executeCommand("undo")&&window.currentSession().snapshot()["charts"]==before["charts"],"deleting a chart must be one reversible transaction");}
void moveFigure(){MainWindow window;window.loadFinancialExample();window.show();QApplication::processEvents();auto* chart=firstChart(window);auto* grid=window.findChild<QTableView*>("worksheet.grid");const auto before=window.currentSession().snapshot();const QPoint delta(37,29),press(140,25),expected=chart->pos()+delta;QTest::mousePress(chart,Qt::LeftButton,Qt::NoModifier,press);QTest::mouseRelease(chart,Qt::LeftButton,Qt::NoModifier,press+delta);QApplication::processEvents();const auto after=window.currentSession().snapshot();const auto anchor=after["charts"][0]["anchor"];const int row=grid->rowAt(expected.y()),col=grid->columnAt(expected.x());
 require(anchor.value("row",0)==row+1&&anchor.value("col",0)==col+1&&anchor.value("offsetX",-1)==expected.x()-grid->columnViewportPosition(col)&&anchor.value("offsetY",-1)==expected.y()-grid->rowViewportPosition(row),"dragging must store the chart's anchored cell and exact pixel offsets");window.recalculateNow();require(firstChart(window)->pos()==expected,"recalculation must retain the chart's dragged position");QTemporaryDir directory;const auto path=directory.filePath("moved.xlsx");require(window.saveWorkbook(path),"moved chart saves");const auto reopened=readWorkbook(path.toStdString()).workbook;require(reopened["charts"][0]["anchor"]==anchor,"chart placement must survive XLSX save/reopen");require(window.executeCommand("undo")&&window.currentSession().snapshot()["charts"]==before["charts"],"one undo must restore the complete pre-drag chart");}
void preserveSelection(){MainWindow window;window.loadFinancialExample();window.show();QApplication::processEvents();QPointer<ChartWidget> chart=firstChart(window);QTest::mouseClick(chart,Qt::LeftButton,Qt::NoModifier,QPoint(120,25));require(chart&&chart->isSelected(),"a chart can be selected");window.recalculateNow();require(chart&&chart->isSelected()&&firstChart(window)==chart,"recalculation must preserve the selected chart and its active widget");}
void anchoredColumnResize(){MainWindow window;window.loadFinancialExample();window.show();QApplication::processEvents();auto* grid=window.findChild<QTableView*>("worksheet.grid");auto* chart=firstChart(window);const auto before=window.currentSession().snapshot();const auto anchor=before["charts"][0]["anchor"];const auto oldPosition=chart->pos();grid->setColumnWidth(0,grid->columnWidth(0)+47);QApplication::processEvents();const auto cell=grid->visualRect(grid->model()->index(anchor.value("row",12)-1,anchor.value("col",4)-1));const QPoint expected(cell.x()+anchor.value("offsetX",0),cell.y()+anchor.value("offsetY",0));require(chart->pos()==expected&&chart->pos().x()==oldPosition.x()+47,"resizing a worksheet column must immediately keep the chart on its anchored cell");require(window.currentSession().snapshot()==before,"layout-only chart positioning must not create workbook transactions");}
void workbookSwitchClearsCharts(){MainWindow window;window.loadFinancialExample();window.show();QApplication::processEvents();require(firstChart(window),"first workbook has a chart");QTemporaryDir directory;const auto path=directory.filePath("empty.xlsx");writeWorkbook(path.toStdString(),WorkbookSession().snapshot());require(window.openWorkbook(path),"second workbook opens");require(firstChart(window)==nullptr,"changing workbooks must immediately remove the previous workbook's interactive charts");}
int main(int argc,char** argv){QApplication app(argc,argv);QTemporaryDir state;qputenv("TIGERSHEETS_STATE_DIR",state.path().toUtf8());try{const auto selected=argc>1?std::string(argv[1]):std::string();for(auto test:{std::pair{"edit",editFigure},std::pair{"delete",deleteFigure},std::pair{"move",moveFigure},std::pair{"selection",preserveSelection},std::pair{"anchor",anchoredColumnResize},std::pair{"switch",workbookSwitchClearsCharts}})if(selected.empty()||selected==test.first)test.second();std::cout<<"chart workspace tests passed\n";}catch(const std::exception& error){std::cerr<<"FAILED: "<<error.what()<<'\n';return 1;}}
